class TaskAttachmentPeer extends BaseTaskAttachmentPeer
{
    public static function getTaskBpmnAttachmentStorage($regional_id)
    {
        //RUTA Y ESTRUCTURA DE ARCHIVOS
        $dirRaiz = ParametroPeer::retrieveByPk(9)->getValortexto();
        $dirTemp = ParametroPeer::retrieveByPk(65)->getValortexto();
        $dirWorkflow = "AdjWorkFlow";
        //********************************************************************************
        $regional = RegionalPeer::retrieveByPK($regional_id);
        $entidad_folder = $regional->getEntidad()->getDirectorioName();
        $regional_folder = $regional->getDirectorioName();
        //********************************************************************************
        $entidad_text = $entidad_folder . '/' . $regional_folder;
        $directorio_entidad = $dirRaiz . $entidad_folder;
        $directorio_tmp = $directorio_entidad . "/" . $dirTemp . "/";
        $path_target = $dirRaiz . $entidad_text . "/" . $dirWorkflow;
        //********************************************************************************
        simad_util::createPath($path_target);
        simad_util::createPath($directorio_tmp);
        //********************************************************************************
        return [
            'directorio_entidad' => $directorio_entidad,
            'directorio_tmp' => $directorio_tmp,
            'path_target' => $path_target,
            'dirWorkflow' => $dirWorkflow,
            'path_raiz' => $dirRaiz,
            'path_relative' => $entidad_text . "/" . $dirWorkflow,
        ];
    }

    /**
     * Procesa archivos subidos en una tarea
     */
    public static function processTaskAttachments($taskId, $request, $user_id)
    {
        $task = TaskInstancePeer::retrieveByPK($taskId);

        if (!$task) {
            throw new Exception('Tarea no encontrada');
        }

        $attachmentIds = [];
        $regional = $task->getWorkflowInstance()->getBpmnProcess()->getUsuario()->getRegional();
        $storage_info = self::getTaskBpmnAttachmentStorage($regional->getPrimaryKey());
        $uploadDir = $storage_info['path_target'] . DIRECTORY_SEPARATOR . date('Ymd');
        $relativePath = $storage_info['path_relative'] . DIRECTORY_SEPARATOR . date('Ymd');

        // Crear directorio si no existe
        if (!is_dir($uploadDir)) {
            simad_util::createPath($uploadDir);
        }


        $ifiles = $request->getFiles();
        if (empty($ifiles) || !is_array($ifiles["attachments"])) {
            return $attachmentIds;
        }

        // Procesar cada archivo
        foreach ($ifiles["attachments"] as $fieldName => $file) {
            if ($file['error'] === UPLOAD_ERR_OK) {
                // Generar nombre único
                $extension = pathinfo($file['name'], PATHINFO_EXTENSION);
                $filename = uniqid() . '_' . time() . '.' . $extension;
                $fullPath = $uploadDir . DIRECTORY_SEPARATOR . $filename;

                // Mover archivo
                if (@move_uploaded_file($file['tmp_name'], $fullPath)) {
                    try {
                        // Crear registro en BD
                        $attachment = new TaskAttachment();
                        $attachment->setTaskInstanceId($taskId);
                        $attachment->setWorkflowInstanceId($task->getWorkflowInstanceId());
                        $attachment->setUsuarioId($user_id);
                        $attachment->setFilename($filename);
                        $attachment->setOriginalFilename($file['name']);
                        $attachment->setPathAbsolute($storage_info['path_raiz']);
                        $attachment->setPathRelative($relativePath);
                        $attachment->setFileSize($file['size']);
                        $attachment->setMimeType($file['type']);

                        // Determinar si es público (parámetro opcional)
                        $isPublic = $request->getParameter('is_public_' . $fieldName, true);
                        $attachment->setIsPublic($isPublic);

                        $description = $request->getParameter('description_' . $fieldName, '');
                        if ($description) {
                            $attachment->setDescription($description);
                        }

                        $attachment->setFechaCreacion(date('Y-m-d G:i:s'));
                        $attachment->setFechaModificacion(date('Y-m-d G:i:s'));
                        $attachment->save();

                        $attachmentIds[] = [
                            'id' => $attachment->getPrimaryKey(),
                            'filename' => $file['name'],
                            'size' => $file['size']
                        ];
                    } catch (Exception $e) {
                        // Manejar error
                        error_log('Error al guardar archivo: ' . $e->getMessage());
                    }
                }
            }
        }

        return $attachmentIds;
    }

    /**
     * Obtiene los archivos adjuntos de un workflow
     */
    public static function getWorkflowAttachments($workflowInstanceId)
    {
        $attachments = [];

        $c = new Criteria();
        $c->add(TaskAttachmentPeer::WORKFLOWINSTANCE_ID, $workflowInstanceId);
        $c->add(TaskAttachmentPeer::IS_PUBLIC, true); // Solo archivos públicos
        $c->addDescendingOrderByColumn(TaskAttachmentPeer::FECHA_CREACION);

        $files = TaskAttachmentPeer::doSelect($c);

        foreach ($files as $file) {
            // Obtener nombre del usuario que subió
            $uploadedByName = 'Sistema';
            if ($file->getUsuarioId()) {
                $uploadedByName = $file->getUsuario()->getNombreApellido();
            }

            $attachments[] = [
                'id' => $file->getPrimaryKey(),
                'filename' => $file->getFilename(),
                'original_filename' => $file->getOriginalFilename(),
                'file_size' => $file->getFileSize(),
                'mime_type' => $file->getMimeType(),
                'uploaded_by' => $file->getUsuarioId(),
                'uploaded_by_name' => $uploadedByName,
                'created_at' => $file->getFechaCreacion('c')
            ];
        }

        return $attachments;
    }
}
